import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import API_BASE_URL from "../config";

const BrowseRentals = () => {
  const [rentals, setRentals] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/rentals`)
      .then((res) => res.json())
      .then((data) => setRentals(data));
  }, []);

  return (
    <div>
      <h1>Available Rentals</h1>
      {rentals.map((rental) => (
        <div key={rental.id}>
          <h3>{rental.title}</h3>
          <p>{rental.description}</p>
          <p>${rental.price} / {rental.duration}</p>
          {rental.image && <img src={rental.image} alt="rental" width="150" />}
          <button onClick={() => navigate(`/rental-checkout/${rental.id}`)}>Rent Now</button>
        </div>
      ))}
    </div>
  );
};

export default BrowseRentals;
